// M7 - Get Task Status (RFC-089 §5.5.1)
// Endpoint de polling pour les opérations async

const input = $input.first().json;
const query = input.query || {};
const taskId = query.task_id;

if (!taskId) {
  return [{
    json: {
      error: true,
      response: {
        success: false,
        error: {
          code: 'missing_task_id',
          message: 'Query parameter task_id is required'
        }
      },
      httpCode: 400
    }
  }];
}

// Récupérer le status depuis staticData
const staticData = $getWorkflowStaticData('global');
const tasks = staticData.asyncTasks || {};
const task = tasks[taskId];

if (!task) {
  return [{
    json: {
      error: true,
      response: {
        success: false,
        error: {
          code: 'task_not_found',
          message: `Task ${taskId} not found or expired`
        }
      },
      httpCode: 404
    }
  }];
}

// Vérifier si le task a expiré
if (task.expiresAt && Date.now() > task.expiresAt) {
  delete tasks[taskId];
  staticData.asyncTasks = tasks;

  return [{
    json: {
      error: true,
      response: {
        success: false,
        error: {
          code: 'task_expired',
          message: `Task ${taskId} has expired`
        }
      },
      httpCode: 410
    }
  }];
}

// Construire la réponse de status
const response = {
  task_id: taskId,
  status: task.status,
  created_at: task.createdAt
};

if (task.status === 'processing' || task.status === 'pending') {
  response.progress = task.progress || null;
  response.message = 'Operation in progress';
}

if (task.status === 'completed') {
  response.completed_at = task.completedAt;
  response.result = task.result;
}

if (task.status === 'error') {
  response.error = task.error;
}

return [{
  json: {
    error: false,
    response: {
      success: true,
      ...response
    },
    httpCode: 200
  }
}];

